import{_ as a,o as l,c as n,am as s}from"./chunks/framework.CiF4W93w.js";const u=JSON.parse('{"title":"面试煎熬成蛋_MySQL","description":"","frontmatter":{"title":"面试煎熬成蛋_MySQL","excerpt":"面试煎熬成蛋_MySQL","date":"2024-03-10 19:49:19","updated":"2024-03-10 19:49:19"},"headers":[],"relativePath":"Java面试准备/面试煎熬成蛋_框架/面试煎熬成蛋_MySQL.md","filePath":"Java面试准备/面试煎熬成蛋_框架/面试煎熬成蛋_MySQL.md","lastUpdated":null}'),o={name:"Java面试准备/面试煎熬成蛋_框架/面试煎熬成蛋_MySQL.md"};function e(p,i,t,c,r,h){return l(),n("div",null,[...i[0]||(i[0]=[s('<h3 id="基础" tabindex="-1">基础 <a class="header-anchor" href="#基础" aria-label="Permalink to &quot;基础&quot;">​</a></h3><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240313172759.png" alt="image.png"></p><h3 id="优化-索引" tabindex="-1">优化/索引 <a class="header-anchor" href="#优化-索引" aria-label="Permalink to &quot;优化/索引&quot;">​</a></h3><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240313164115.png" alt="image.png"></p><h4 id="在-mysql-中-如何定位慢查询" tabindex="-1">在 MySQL 中，如何定位慢查询？ <a class="header-anchor" href="#在-mysql-中-如何定位慢查询" aria-label="Permalink to &quot;在 MySQL 中，如何定位慢查询？&quot;">​</a></h4><ul><li>聚合查询</li><li>多表查询</li><li>表数据量过大查询</li><li>深度分页查询</li></ul><p>表象：页面加载过慢、接口压测响应时间过长（超过 1s ）</p><p>方案一、开源工具</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305204256.png" alt="image.png"></p><p>方案二： MySQL 自带慢日志</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305204349.png" alt="image.png"></p><p>总结：</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305204413.png" alt="image.png"></p><p>（生产阶段一般不开启慢日志查询）</p><p>开源采用 EXPLAIN 或者 DESC 命令获取 MySQL 如何执行 SELECT 语句的信息</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305205010.png" alt="image.png"></p><p>参数使用</p><ul><li>possible_key 当前 sql 可能会使用到的索引</li><li>key 当前 sql 实际命中的索引</li><li>key_len 索引占用的大小</li><li>Extra 额外的优化建议</li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305204719.png" alt="image.png"></p><ul><li>type</li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305204847.png" alt="image.png"></p><p>总结</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305204938.png" alt="image.png"></p><h4 id="什么是索引-🚩" tabindex="-1">什么是索引 🚩 <a class="header-anchor" href="#什么是索引-🚩" aria-label="Permalink to &quot;什么是索引  🚩&quot;">​</a></h4><p>这里先讲一下 MySQL 的的基础结构，讲一下优化器的选择，再讲一下选择索引选择（主键索引和从表索引）</p><p>提高访问效率，索引是某种数据结构组成</p><p>索引(index)是帮助 MySQL 高效获取数据的数据结构 (有序) 。</p><p>在数据之外，数据库系统还维护着满足特定查找算法的数据结构(B+树)，这些数据结构以某种方式引用（指向）数据，这样就可以在这些数据结构上实现高级查找算法，这种数据结构就是索引。</p><h4 id="讲一下索引的底层结构" tabindex="-1">讲一下索引的底层结构 <a class="header-anchor" href="#讲一下索引的底层结构" aria-label="Permalink to &quot;讲一下索引的底层结构&quot;">​</a></h4><ul><li>目前索引采用的底层结构是 B+ 树</li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305211546.png" alt="image.png"></p><h4 id="什么是聚簇索引-什么是非聚簇索引" tabindex="-1">什么是聚簇索引，什么是非聚簇索引 <a class="header-anchor" href="#什么是聚簇索引-什么是非聚簇索引" aria-label="Permalink to &quot;什么是聚簇索引，什么是非聚簇索引&quot;">​</a></h4><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305212233.png" alt="image.png"></p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305212341.png" alt="image.png"></p><p>讲一下回表查询</p><p>回表查询：通过二级索引找到对应的主键值</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305212500.png" alt="image.png"></p><blockquote><p>知道什么是覆盖索引吗</p></blockquote><p>对查询列有要求，一般是查询的字段和索引字段相同，不同走主键查询那步，直接从索引树上查询出了数据</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305212622.png" alt="image.png"></p><p>你看一下这个例子，主键索引中查询条件是主键的话，直接查询所有数据是话算是覆盖索引，然后如果是二级索引，查询 主键+ 索引 是算覆盖索引查询(索引树上直接查询)</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305212749.png" alt="image.png"></p><p>覆盖索引的基本介绍</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305213542.png" alt="image.png"></p><h4 id="mysql-超大分页怎么处理" tabindex="-1">MySQL 超大分页怎么处理 <a class="header-anchor" href="#mysql-超大分页怎么处理" aria-label="Permalink to &quot;MySQL 超大分页怎么处理&quot;">​</a></h4><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305213731.png" alt="image.png"></p><p>提供一种解决思路：通过覆盖索引 + 子查询 形式进行优化 、</p><ul><li>先通过覆盖索引查询出对应的ID，然后通过关联查询，查询出分页数据</li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305214250.png" alt="image.png"></p><p>总结</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305214458.png" alt="image.png"></p><h4 id="索引创建原则" tabindex="-1">索引创建原则 <a class="header-anchor" href="#索引创建原则" aria-label="Permalink to &quot;索引创建原则&quot;">​</a></h4><p>回答思路：</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305214539.png" alt="image.png"></p><p>主要的一些原则：</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305214712.png" alt="image.png"></p><p>索引创建原则有哪些？</p><ul><li><ol><li>数据量较大，且查询比较频繁的表 <strong>重要</strong></li></ol></li><li>2).常作为查询条件、排序、分组的字段 <strong>重要</strong></li><li>3).字段内容区分度高</li><li>4).内容较长，使用前缀索引</li><li>5).尽量联合索引 <strong>重要</strong></li><li>6).要控制索引的数量 <strong>重要</strong></li><li>7).如果索引列不能存储NULL 值，请在创建表时使用NOT NULL 约束它</li></ul><h4 id="索引失效" tabindex="-1">索引失效 <a class="header-anchor" href="#索引失效" aria-label="Permalink to &quot;索引失效&quot;">​</a></h4><p>如何判断索引是否失效：通过 执行计划 explain</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305222045.png" alt="image.png"></p><p>索引失效的一些情况：</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305222317.png" alt="image.png"></p><p>理解去记忆一下</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305222354.png" alt="image.png"></p><h4 id="谈谈你对-sql-优化的经验" tabindex="-1">谈谈你对 SQL 优化的经验 <a class="header-anchor" href="#谈谈你对-sql-优化的经验" aria-label="Permalink to &quot;谈谈你对 SQL 优化的经验&quot;">​</a></h4><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305222506.png" alt="image.png"></p><ul><li>主从复制、读写分离</li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305222712.png" alt="image.png"></p><p>总结：</p><ul><li>1、表的设计优化，数据类型的选择</li><li>2、索引优化，索引创建原则、</li><li>3、sql语句优化，避免索引失效，避免使用select * ....</li><li>4、主从复制、读写分离，不让数据的写入，影响读操作</li><li>5、分库分表</li></ul><h4 id="最左匹配原则" tabindex="-1">最左匹配原则 <a class="header-anchor" href="#最左匹配原则" aria-label="Permalink to &quot;最左匹配原则&quot;">​</a></h4><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240313161701.png" alt="image.png"></p><h4 id="索引下推" tabindex="-1">索引下推 <a class="header-anchor" href="#索引下推" aria-label="Permalink to &quot;索引下推&quot;">​</a></h4><h3 id="锁" tabindex="-1">锁 <a class="header-anchor" href="#锁" aria-label="Permalink to &quot;锁&quot;">​</a></h3><ul><li>悲观锁</li><li>乐观锁</li><li>表锁</li><li>行锁（Innodb 存储引擎）</li></ul><p>悲观锁实现</p><p>可以通过SQL语句显式地对选定的行进行锁定，直到当前事务结束。</p><ul><li><strong>SELECT ... FOR UPDATE</strong>: 对读取的行加上排他锁（X锁）。其他事务将不能读取或修改这些行。</li><li><strong>SELECT ... LOCK IN SHARE MODE</strong>: 对读取的行加上共享锁（S锁）。其他事务可以读取但不能修改这些行。</li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/6b0487b3cd1209dc0a3ee87a09fe6f9.png" alt="6b0487b3cd1209dc0a3ee87a09fe6f9.png"></p><ul><li><p>update 没加索引会锁全表？</p></li><li><p><a href="https://xiaolincoding.com/mysql/lock/update_index.html" target="_blank" rel="noreferrer">https://xiaolincoding.com/mysql/lock/update_index.html</a></p></li></ul><h3 id="事务" tabindex="-1">事务 <a class="header-anchor" href="#事务" aria-label="Permalink to &quot;事务&quot;">​</a></h3><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240313164140.png" alt="image.png"></p><h4 id="事务的特性" tabindex="-1">事务的特性 <a class="header-anchor" href="#事务的特性" aria-label="Permalink to &quot;事务的特性&quot;">​</a></h4><p>事务：事务是一组操作的集合，它是一个不可分割的工作单位，事务会把所有的操作作为一个整体一起向系 统提交或撤销操作请求，即这些操作要么同时成功，要么同时失败。</p><p>ACID是什么？可以详细说一下吗？</p><ul><li>原子性(Atomicity):事务是不可分割的最小操作单元，要么全部成功，要么全部失败。</li><li>一致性(Consistency):事务完成时，必须使所有的数据都保持一致状态。</li><li>隔离性(Isolation)：数据库系统提供的隔离机制，保证事务在不受外部并发操作影响的独立环境下运行。</li><li>持久性(Durability)：事务一旦提交或回滚，它对数据库中的数据的改变就是永久的。</li></ul><p>讲述这种题目的适合最好结合一下实际案例来讲述一下，让面试官觉得你讲的和其他人有所不同</p><p>示例：</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305223200.png" alt="image.png"></p><hr><h4 id="并发事务带来哪些问题-怎么解决这些问题呢-mysql-的隔离级别是" tabindex="-1">并发事务带来哪些问题？怎么解决这些问题呢？MySQL 的隔离级别是？ <a class="header-anchor" href="#并发事务带来哪些问题-怎么解决这些问题呢-mysql-的隔离级别是" aria-label="Permalink to &quot;并发事务带来哪些问题？怎么解决这些问题呢？MySQL 的隔离级别是？&quot;">​</a></h4><ul><li>并发事务问题：脏读、不可重复读、幻读</li><li>隔离级别：读未提交、读已提交、可重复读、串行化</li></ul><p>并发事务问题</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305223338.png" alt="image.png"></p><p>怎么解决并发事务的问题？</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305223402.png" alt="image.png"></p><p>注意：事务隔离级别越高，数据越安全，但是性能越低。</p><p>总结：</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305223512.png" alt="image.png"></p><h4 id="解释一下-mvcc" tabindex="-1">解释一下 MVCC <a class="header-anchor" href="#解释一下-mvcc" aria-label="Permalink to &quot;解释一下 MVCC&quot;">​</a></h4><h3 id="日志" tabindex="-1">日志 <a class="header-anchor" href="#日志" aria-label="Permalink to &quot;日志&quot;">​</a></h3><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240313165349.png" alt="image.png"></p><h4 id="undo-log-和-redo-log-的区别" tabindex="-1">undo log 和 redo log 的区别？ <a class="header-anchor" href="#undo-log-和-redo-log-的区别" aria-label="Permalink to &quot;undo log  和 redo log 的区别？&quot;">​</a></h4><p>先引入一个概念：即缓存池和数据页，数据页是磁盘中实际存储的数据，但一般数据加载的时候会先从内存中到磁盘，这个内存的区域叫做缓冲池。</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305223637.png" alt="image.png"></p><p>服务宕机的时候，数据如何保证不丢失，是由于日志的存在。</p><ul><li>redo log：</li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305231922.png" alt="image.png"></p><ul><li>undo log</li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305232004.png" alt="image.png"></p><p>总结：</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305232037.png" alt="image.png"></p><h3 id="高级功能" tabindex="-1">高级功能 <a class="header-anchor" href="#高级功能" aria-label="Permalink to &quot;高级功能&quot;">​</a></h3><h4 id="讲一下-主从同步原理" tabindex="-1">讲一下 主从同步原理 <a class="header-anchor" href="#讲一下-主从同步原理" aria-label="Permalink to &quot;讲一下 主从同步原理&quot;">​</a></h4><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240313171348.png" alt="image.png"></p><h4 id="讲一下-分库分表" tabindex="-1">讲一下 分库分表 <a class="header-anchor" href="#讲一下-分库分表" aria-label="Permalink to &quot;讲一下 分库分表&quot;">​</a></h4><p>分表是指将一个大表拆分成多个小表的过程。</p><p>这些小表可以分布在同一个数据库或多个数据库中。分表通常基于某些关键字段进行，比如时间、用户ID等。</p><ul><li><strong>垂直分表</strong>：将表中不同的列分到不同的表中。例如，一个用户表可以被分成用户基础信息表和用户详细信息表。</li><li><strong>水平分表</strong>：根据行数据将表分成多个表，每个表包含相同的列，但只包含部分行。例如，基于用户ID范围或创建时间进行切分。</li></ul><p>分库涉及将数据分布到多个数据库实例上。每个数据库实例可以托管在不同的服务器上，从而分散负载和提高容错能力。</p><ul><li><strong>分布式数据库</strong>：数据被分散存储在多个物理位置，每个数据库实例可以独立处理查询和事务。</li><li><strong>读写分离</strong>：常与分库结合使用，读操作和写操作分别在不同的数据库实例上进行。</li></ul><h4 id="读写分离" tabindex="-1">读写分离 <a class="header-anchor" href="#读写分离" aria-label="Permalink to &quot;读写分离&quot;">​</a></h4><p>读写分离涉及将数据库的读取操作（SELECT查询）和写入操作（INSERT、UPDATE、DELETE）分离到不同的服务器上。</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240313170248.png" alt="image.png"></p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240313170226.png" alt="image.png"></p>',126)])])}const m=a(o,[["render",e]]);export{u as __pageData,m as default};
